import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom'; // Thư viện trung gian điều hướng
import { apiDangNhap, apiDangKy } from '../api/goi_api';
import bgImage from '../assets/background.jpg'; 

const DangNhap = () => {
    const navigate = useNavigate();

    // State quản lý: Chế độ (Đăng nhập/Đăng ký) và dữ liệu Form
    const [isRegister, setIsRegister] = useState(false);
    const [form, setForm] = useState({ 
        ten: '', 
        mk: '', 
        reMk: '', 
        role: 'CuDan', 
        maNoiBo: '' 
    });

    const handleAction = async (e) => {
        e.preventDefault();
        try {
            if (!isRegister) {
                // XỬ LÝ ĐĂNG NHẬP
                await apiDangNhap({ ten_dang_nhap: form.ten, mat_khau: form.mk });
                alert("Đăng nhập thành công!");
                navigate('/dashboard'); // Bay thẳng vào Dashboard
            } else {
                // XỬ LÝ ĐĂNG KÝ
                if (form.mk !== form.reMk) return alert("Mật khẩu không khớp!");
                await apiDangKy(form);
                alert("Đăng ký thành công! Hãy đăng nhập lại.");
                setIsRegister(false); // Đăng ký xong tự lật về Đăng nhập
            }
        } catch (error) {
            console.error(error);
            alert("Lỗi! Kiểm tra lại thông tin hoặc Server.");
            // navigate('/dashboard'); // Bỏ comment dòng này nếu muốn test Dashboard mà ko cần Backend
        }
    };

    return (
        <div style={styles.container}>
            <div style={styles.loginBox}>

                {/* Cột trái: Banner (Giữ nguyên cấu trúc nhưng đổi chữ theo State) */}
                <div style={styles.leftSide}>
                    <div style={styles.logoContainer}>
                        <span style={styles.icon}>🏬</span>
                        <h1 style={styles.brandName}>A&RMS</h1>
                    </div>
                    <div style={styles.welcomeText}>
                        <p style={styles.mainWelcome}>
                            {isRegister ? "Khởi tạo tài khoản mới," : "Chào mừng đã đến với A&RMS,"}
                        </p>
                        <p style={styles.subWelcome}>Phần mềm quản lý căn hộ và khu dân cư!</p>
                    </div>
                </div>

                {/* Cột phải: Form thay đổi ruột tại chỗ */}
                <div style={styles.rightSide}>
                    <h2 style={styles.title}>
                        {isRegister ? "Đăng Ký Thành Viên" : "Apartment & Resident Management System"}
                    </h2>

                    <form onSubmit={handleAction} style={styles.form}>
                        {/* 1. Phần chọn Vai trò & Mã đỏ (Chỉ hiện khi Đăng ký) */}
                        {isRegister && (
                            <div style={styles.roleBox}>
                                <div style={styles.radioGroup}>
                                    <label style={styles.label}>
                                        <input type="radio" checked={form.role === 'CuDan'} onChange={() => setForm({...form, role: 'CuDan'})} /> Cư dân
                                    </label>
                                    <label style={styles.label}>
                                        <input type="radio" checked={form.role === 'QuanLy'} onChange={() => setForm({...form, role: 'QuanLy'})} /> Quản lý
                                    </label>
                                </div>
                                {form.role === 'QuanLy' && (
                                    <input 
                                        type="text" placeholder="6 số" style={styles.redInput}
                                        onChange={(e) => setForm({...form, maNoiBo: e.target.value})}
                                    />
                                )}
                            </div>
                        )}

                        {/* 2. Các ô nhập liệu cơ bản */}
                        <input type="text" placeholder="Tài khoản ..." style={styles.input} required
                            onChange={(e) => setForm({...form, ten: e.target.value})} />

                        <input type="password" placeholder="Mật khẩu ..." style={styles.input} required
                            onChange={(e) => setForm({...form, mk: e.target.value})} />

                        {/* 3. Ô nhập lại mật khẩu (Chỉ hiện khi Đăng ký) */}
                        {isRegister && (
                            <input type="password" placeholder="Nhập lại mật khẩu ..." style={styles.input} required
                                onChange={(e) => setForm({...form, reMk: e.target.value})} />
                        )}

                        <button type="submit" style={styles.loginBtn}>
                            {isRegister ? "Xác nhận Đăng ký" : "Đăng nhập"}
                        </button>
                    </form>

                    <div style={styles.footer}>
                        <span 
                            style={styles.registerLink} 
                            onClick={() => setIsRegister(!isRegister)}
                        >
                            {isRegister ? "Quay lại Đăng nhập" : "Đăng ký tài khoản mới"}
                        </span>
                    </div>
                </div>
            </div>
        </div>
    );
};

const styles = {
    container: {
        height: '100vh', display: 'flex', justifyContent: 'center', alignItems: 'center',
        backgroundImage: `linear-gradient(rgba(0,0,0,0.5), rgba(0,0,0,0.5)), url(${bgImage})`,
        backgroundSize: 'cover', backgroundPosition: 'center',
        fontFamily: "'Inter', sans-serif",
    },
    loginBox: {
        display: 'flex', width: '900px', height: '520px', backgroundColor: 'rgba(255, 255, 255, 0.95)',
        borderRadius: '20px', boxShadow: '0 25px 50px rgba(0,0,0,0.3)', overflow: 'hidden',
    },
    leftSide: {
        flex: 1, backgroundColor: '#1c1c1c', padding: '50px', color: '#ffffff',
        display: 'flex', flexDirection: 'column', justifyContent: 'center',
    },
    logoContainer: { display: 'flex', alignItems: 'center', gap: '12px', marginBottom: '30px' },
    icon: { fontSize: '35px' },
    brandName: { fontSize: '32px', fontWeight: 'bold', margin: 0, letterSpacing: '1px' },
    welcomeText: { lineHeight: '1.6' },
    mainWelcome: { fontSize: '18px', fontWeight: '600', marginBottom: '8px' },
    subWelcome: { fontSize: '14px', opacity: 0.8 },
    rightSide: {
        flex: 1.3, padding: '40px 60px', display: 'flex', flexDirection: 'column', justifyContent: 'center',
    },
    title: { fontSize: '19px', color: '#444', textAlign: 'center', marginBottom: '30px' },
    form: { display: 'flex', flexDirection: 'column', gap: '15px' },
    input: {
        width: '100%', padding: '13px 16px', borderRadius: '8px', border: '1px solid #ddd',
        fontSize: '15px', outline: 'none', boxSizing: 'border-box', backgroundColor: '#f9f9f9',
    },
    roleBox: { display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: '5px' },
    radioGroup: { display: 'flex', gap: '15px', fontSize: '14px' },
    label: { cursor: 'pointer', display: 'flex', alignItems: 'center', gap: '5px' },
    redInput: {
        border: '2px solid #a52a2a', borderRadius: '6px', padding: '5px 10px', width: '100px', outline: 'none'
    },
    loginBtn: {
        padding: '14px', backgroundColor: '#4e342e', color: '#fff', border: 'none',
        borderRadius: '8px', fontSize: '16px', fontWeight: 'bold', cursor: 'pointer', marginTop: '10px',
    },
    footer: { marginTop: '20px', textAlign: 'center' },
    registerLink: { color: '#2e7d32', cursor: 'pointer', fontSize: '14px', fontWeight: '500' }
};

export default DangNhap;
